import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  contextMenuBackdropClassName,
  contextMenuItemClassName,
  contextMenuPopupClassName,
  contextMenuPortalClassName,
  contextMenuPositionerClassName,
  contextMenuRootClassName,
  contextMenuSeparatorClassName,
  contextMenuTriggerClassName,
} from "./view";

export {
  contextMenuBackdropClassName,
  contextMenuItemClassName,
  contextMenuPopupClassName,
  contextMenuPortalClassName,
  contextMenuPositionerClassName,
  contextMenuRootClassName,
  contextMenuSeparatorClassName,
  contextMenuTriggerClassName,
} from "./view";

export type ContextMenuStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  onOpen: ParentMessage;
  children: readonly Html[];
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

export type PartViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

export type BackdropViewConfig<ParentMessage> = Readonly<{
  onClose: ParentMessage;
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  onSelect: ParentMessage;
  children: readonly Html[];
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ContextMenuStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuRootClassName, className)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  onOpen,
  children,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("aria-haspopup", "menu"),
      h.OnClick(onOpen),
      h.OnContextMenu(onOpen),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuTriggerClassName, className)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  className,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuPortalClassName, className)),
    ],
    children
  );
};

export const positionerView = <ParentMessage>({
  children,
  className,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuPositionerClassName, className)),
    ],
    children
  );
};

export const backdropView = <ParentMessage>({
  onClose,
  className,
  style,
}: BackdropViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("aria-label", "Close context menu"),
      h.OnClick(onClose),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuBackdropClassName, className)),
    ],
    []
  );
};

export const popupView = <ParentMessage>({
  children,
  className,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menu"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuPopupClassName, className)),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  onSelect,
  children,
  disabled = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitem"),
      h.Disabled(disabled),
      ...(disabled ? [h.Attribute("data-disabled", "")] : []),
      h.OnClick(onSelect),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuItemClassName, className)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  className,
  style,
}: Omit<PartViewConfig, "children">): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(contextMenuSeparatorClassName, className)),
    ],
    []
  );
};

export const contextMenuRootClassName = "relative inline-block";

export const contextMenuTriggerClassName =
  "flex min-h-36 min-w-64 items-center justify-center rounded-lg border border-dashed border-gray-300 bg-white px-6 py-8 text-base font-medium text-gray-700 transition hover:border-gray-400 hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

export const contextMenuPortalClassName = "contents";

export const contextMenuBackdropClassName =
  "fixed inset-0 z-10 cursor-default bg-transparent";

export const contextMenuPositionerClassName = "absolute left-6 top-6 z-20";

export const contextMenuPopupClassName =
  "w-56 overflow-hidden rounded-lg border border-gray-200 bg-white py-1 shadow-lg outline-none";

export const contextMenuItemClassName =
  "w-full px-3 py-2 text-left text-base text-gray-700 transition hover:bg-gray-100 focus:bg-gray-100 focus:outline-none data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const contextMenuSeparatorClassName = "my-1 h-px bg-gray-200";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as ContextMenu from ".";

const view = (open: boolean) => {
  const h = html<boolean>();

  return ContextMenu.rootView<boolean>({
    children: [
      ContextMenu.triggerView({
        onOpen: true,
        children: [h.span([], ["Right click here"])],
      }),
      ContextMenu.portalView({
        open,
        children: [
          ContextMenu.backdropView({ onClose: false }),
          ContextMenu.positionerView({
            children: [
              ContextMenu.popupView({
                children: [
                  ContextMenu.itemView({
                    onSelect: false,
                    children: [h.span([], ["Add to Library"])],
                  }),
                  ContextMenu.separatorView({}),
                  ContextMenu.itemView({
                    onSelect: false,
                    disabled: true,
                    children: [h.span([], ["Disabled item"])],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Context Menu registry component", () => {
  test("opens a menu from the context-menu trigger", () => {
    Scene.scene(
      {
        update: (_model: boolean, message: boolean) => [message, []] as const,
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("menu")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Right click here" })),
      Scene.expect(Scene.role("menu")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "Add to Library" })).toExist()
    );
  });

  test("exports Base UI context menu class hooks", () => {
    expect(ContextMenu.contextMenuTriggerClassName).toContain("border-dashed");
    expect(ContextMenu.contextMenuBackdropClassName).toContain("fixed");
    expect(ContextMenu.contextMenuPopupClassName).toContain("shadow");
    expect(ContextMenu.contextMenuSeparatorClassName).toContain("bg-gray-200");
  });
});
